+    buf_lit(b, ",\"token\":");
+    buf_json_str(b, tok, tokn);
+    buf_lit(b, ",\"username\":");
+    emit_str(b, username);
+    buf_lit(b, ",\"bio\":");
+    emit_str(b, bio);
+    buf_lit(b, ",\"image\":");
