+static void create_article_done(req_t *r, pgbatch_t *b) {
+    if (!batch_ok(r, b)) return;
+    const pgst_t *st = &b->st[b->nst - 1];
+    if (st->nrows == 0) { reply_err(r, 500, "internal error"); return; }
