+static void h_delete_article(req_t *r) {
+    pgbatch_t *b = pg_begin(r, delete_done);
+    str_t p[2] = {r->seg[1], viewer_str(r)};
+    pg_stmt(b, S_ARTICLE_AUTHOR, &r->seg[1]);
+    pg_stmt(b, S_DELETE_ARTICLE, p);
+    pg_end(b);
+}
