+        *out = (str_t){s, (size_t)(p - s)};
+        j->p = p + 1;
+        return true;
+    }
+    char *o = arena_alloc(j->a, (p - s) * 3 + 4), *o0 = o;
+    p = s;
+    for (;;) {
+        if (p >= j->end) return false;
+        unsigned char c = *p;
