+    if (p < e && *p == '.') {
+        p++;
+        if (p >= e || *p < '0' || *p > '9') return false;
+        while (p < e && *p >= '0' && *p <= '9') p++;
+    }
+    if (p < e && (*p == 'e' || *p == 'E')) {
+        p++;
+        if (p < e && (*p == '+' || *p == '-')) p++;
+        if (p >= e || *p < '0' || *p > '9') return false;
+        while (p < e && *p >= '0' && *p <= '9') p++;
+    }
+    *out = (str_t){s, (size_t)(p - s)};
+    j->p = p;
+    return true;
+}
+
+static jv_t *parse_value(jp_t *j);
+
+static bool lit(jp_t *j, const char *w, size_t n) {
+    if ((size_t)(j->end - j->p) < n || memcmp(j->p, w, n) != 0) return false;
+    j->p += n;
+    return true;
+}
+
+static jv_t *parse_value(jp_t *j) {
+    ws(j);
+    if (j->p >= j->end) return NULL;
+    jv_t *v = arena_alloc(j->a, sizeof *v);
+    memset(v, 0, sizeof *v);
+    switch (*j->p) {
+    case '{': {
+        if (++j->depth > 1000) return NULL;
+        v->type = J_OBJ;
+        j->p++;
+        ws(j);
+        if (j->p < j->end && *j->p == '}') { j->p++; j->depth--; return v; }
+        jv_t **tail = &v->child;
+        for (;;) {
+            ws(j);
+            if (j->p >= j->end || *j->p != '"') return NULL;
+            str_t key;
+            if (!parse_string(j, &key)) return NULL;
+            ws(j);
+            if (j->p >= j->end || *j->p != ':') return NULL;
+            j->p++;
+            jv_t *m = parse_value(j);
+            if (!m) return NULL;
+            m->key = key;
+            *tail = m;
+            tail = &m->next;
+            ws(j);
+            if (j->p >= j->end) return NULL;
+            if (*j->p == ',') { j->p++; continue; }
+            if (*j->p == '}') { j->p++; break; }
+            return NULL;
+        }
+        j->depth--;
+        return v;
+    }
+    case '[': {
+        if (++j->depth > 1000) return NULL;
+        v->type = J_ARR;
+        j->p++;
+        ws(j);
+        if (j->p < j->end && *j->p == ']') { j->p++; j->depth--; return v; }
+        jv_t **tail = &v->child;
+        for (;;) {
+            jv_t *m = parse_value(j);
+            if (!m) return NULL;
+            *tail = m;
+            tail = &m->next;
+            ws(j);
+            if (j->p >= j->end) return NULL;
+            if (*j->p == ',') { j->p++; continue; }
+            if (*j->p == ']') { j->p++; break; }
+            return NULL;
+        }
+        j->depth--;
+        return v;
+    }
