+struct io_uring_sqe *get_sqe(worker_t *w) {
+    struct io_uring_sqe *sqe = io_uring_get_sqe(&w->ring);
+    while (UNLIKELY(!sqe)) {
+        io_uring_submit(&w->ring);
+        sqe = io_uring_get_sqe(&w->ring);
+    }
+    return sqe;
